1: //! win-1: the `blit` binary's MAIN thread must fit a small stack on every
2: //! platform, not only on the ones that happen to give it 8 MiB.
3: //!
4: //! `#[tokio::main]` polls the whole command future on the process's main
5: //! thread. Windows gives that thread 1 MiB; macOS and Linux give it the
6: //! `RLIMIT_STACK` soft limit, 8 MiB by default. A debug build's async poll
7: //! frames hold every nested future inline, and the SOURCE_SIDE_CONTAINMENT
8: //! work (the ssc-6 retry passes inlined a second session into every route
9: //! arm) pushed the DESTINATION routes past 1 MiB: every local copy, mirror,
10: //! move and pull died on Windows with `thread 'main' has overflowed its
11: //! stack`, while the same suite passed on macOS and Linux. The fix boxes
12: //! the session futures where one large future nests another; this test is
13: //! the guard that makes the same failure visible on the platforms CI and
14: //! developers actually run first.
15: //!
16: //! On Unix every run goes through `sh -c 'ulimit -S -s <BUDGET_KIB> && exec
17: //! blit …'`: the kernel sizes the main thread of the exec'd process from
18: //! the soft limit, so `blit` runs with exactly that much main-thread stack.
19: //! On Windows the binary runs as is — its main thread is the 1 MiB the
20: //! failure happened on.
21: //!
22: //! The budget, measured on macOS aarch64 debug (DEVLOG 2026-09-30,
23: //! "win-1"): before the boxing the shapes below needed 960–1216 KiB of
24: //! main-thread stack (push 960, pull 1024, copy/mirror 1088, mirror with a
25: //! retry pass 1216) — all over this budget; after it every shape needs
26: //! 496 KiB, which is the argument parser's own floor (clap's derived
27: //! `augment_args` frames), not the transfer's.
28: 
29: use std::fs;
30: use std::path::{Path, PathBuf};
31: use std::process::{Command, Output};
32: use std::time::Duration;
33: 
34: mod common;
35: use common::{cli_bin, run_with_timeout, TestContext};
36: 
37: /// The main-thread stack `blit` gets on Unix, in KiB. Red before win-1's
38: /// boxing on every shape here, green after with a ~1.5x margin over the
39: /// parser floor.
40: #[cfg(unix)]
41: const BUDGET_KIB: u32 = 768;
42: 
43: const EXIT_PARTIAL_FAILURE: i32 = 2;
44: 
45: /// `blit <args>` with its main thread held to the budget.
46: fn budgeted_blit(config_dir: Option<&Path>, args: &[String]) -> Command {
47:     #[cfg(unix)]
48:     let mut cmd = {
49:         let mut cmd = Command::new("/bin/sh");
50:         cmd.arg("-c")
51:             .arg(format!("ulimit -S -s {BUDGET_KIB} && exec \"$0\" \"$@\""))
52:             .arg(cli_bin());
53:         cmd
54:     };
55:     #[cfg(windows)]
56:     let mut cmd = Command::new(cli_bin());
57:     if let Some(dir) = config_dir {
58:         cmd.arg("--config-dir").arg(dir);
59:     }
60:     cmd.args(args);
61:     cmd
62: }
63: 
64: fn run(config_dir: Option<&Path>, args: &[String]) -> Output {
65:     run_with_timeout(budgeted_blit(config_dir, args), Duration::from_secs(120))
66: }
67: 
68: fn text(bytes: &[u8]) -> String {
69:     String::from_utf8_lossy(bytes).into_owned()
70: }
71: 
72: /// The run finished with `code` — not a signal, not a stack overflow.
73: fn assert_exit(output: &Output, code: i32, shape: &str) {
74:     let stderr = text(&output.stderr);
75:     assert!(
76:         !stderr.contains("overflowed its stack"),
77:         "{shape}: blit overflowed its main-thread stack\nstderr:\n{stderr}"
78:     );
79:     assert_eq!(
80:         output.status.code(),
81:         Some(code),
82:         "{shape}: unexpected exit ({:?})\nstdout:\n{}\nstderr:\n{stderr}",
83:         output.status,
84:         text(&output.stdout)
85:     );
86: }
87: 
88: /// Small files in subdirectories plus one large enough to ride its own
89: /// record, so the shard and the single-file paths both run.
90: fn source_tree(root: &Path) {
91:     for i in 0..24u8 {
92:         let path = root.join(format!("d{}/f{i}.txt", i % 3));
93:         fs::create_dir_all(path.parent().unwrap()).unwrap();
94:         fs::write(&path, vec![i; 1000 + usize::from(i) * 100]).unwrap();
95:     }
96:     fs::write(root.join("big.bin"), vec![7u8; 3_000_000]).unwrap();
97: }
98: 
99: fn slash(path: &Path) -> String {
100:     format!("{}/", path.display())
101: }
102: 
103: fn args(parts: &[&str]) -> Vec<String> {
104:     parts.iter().map(|part| part.to_string()).collect()
105: }
106: 
107: fn local_fixture() -> (tempfile::TempDir, PathBuf, PathBuf) {
108:     let tmp = tempfile::tempdir().unwrap();
109:     let src = tmp.path().join("src");
110:     let dst = tmp.path().join("dst");
111:     fs::create_dir_all(&src).unwrap();
112:     fs::create_dir_all(&dst).unwrap();
113:     source_tree(&src);
114:     (tmp, src, dst)
115: }
116: 
117: #[test]
118: fn local_copy_fits_the_main_thread_budget() {
119:     let (_tmp, src, dst) = local_fixture();
120:     let mut argv = args(&["copy", "--yes"]);
121:     argv.extend([slash(&src), slash(&dst)]);
122:     assert_exit(&run(None, &argv), 0, "local copy");
123:     assert_eq!(fs::read(dst.join("big.bin")).unwrap(), vec![7u8; 3_000_000]);
124: }
