126: /// Mirror with a retry pass: a DIRECTORY occupies one file's destination
127: /// path, so the main pass reports it, the retry pass runs a second session
128: /// and reports it again, and the run exits 2.
129: #[test]
130: fn local_mirror_with_a_retry_pass_fits_the_main_thread_budget() {
131:     let (_tmp, src, dst) = local_fixture();
132:     fs::create_dir_all(dst.join("d0/f0.txt")).unwrap();
133:     fs::write(dst.join("stale.txt"), b"extraneous").unwrap();
134:     let mut argv = args(&[
135:         "mirror",
136:         "--yes",
137:         "--retries",
138:         "1",
139:         "--diagnostics-no-retry-wait",
140:     ]);
141:     argv.extend([slash(&src), slash(&dst)]);
142:     let output = run(None, &argv);
143:     assert_exit(&output, EXIT_PARTIAL_FAILURE, "local mirror + retry");
144:     assert!(
