51: /// Run the future `make` builds to completion on a fresh thread whose
52: /// stack is exactly `stack` bytes, polled by a current-thread runtime on
53: /// that thread. An overflow aborts the test process, which fails the
54: /// test — there is no way to catch it, and none is wanted.
55: fn on_stack_of<F, Fut>(stack: usize, make: F)
56: where
57:     F: FnOnce() -> Fut + Send + 'static,
58:     Fut: Future<Output = ()>,
59: {
60:     std::thread::Builder::new()
61:         .name("stack-budget".into())
62:         .stack_size(stack)
63:         .spawn(move || {
64:             let runtime = tokio::runtime::Builder::new_current_thread()
65:                 .enable_all()
66:                 .build()
67:                 .expect("current-thread runtime");
68:             runtime.block_on(make());
69:         })
70:         .expect("spawn the budgeted thread")
71:         .join()
72:         .expect("the session must complete within the stack budget");
73: }
