262: /// The pass loop, shared by every route. `run` executes one retry pass
263: /// with the prepared arguments (the retry-only set and the pass label
264: /// already threaded in) and returns that pass's result.
265: pub(crate) async fn run_retry_passes<F, Fut>(
266:     args: &TransferArgs,
267:     main: PassFailures,
268:     mut run: F,
269: ) -> Result<RetryOutcome>
270: where
271:     F: FnMut(TransferArgs) -> Fut,
272:     Fut: Future<Output = Result<PassResult>>,
273: {
274:     let mut current = main;
275:     let mut added_files = 0u64;
276:     let mut added_bytes = 0u64;
277:     let mut passes_run = 0u32;
278:     let mut in_stream_carrier_used = false;
279:     let mut files_resumed = 0u64;
280:     // A dry run writes nothing, so nothing it reported can converge by
281:     // retrying; the report stands as the first pass produced it.
282:     let retries = if args.dry_run { 0 } else { args.retries };
283:     for pass in 1..=retries {
284:         if current.files_failed == 0 {
285:             break;
286:         }
287:         let (set, truncated) = current.retry_set();
288:         if set.is_empty() {
289:             break;
290:         }
291:         let total = retries;
292:         let n = set.len();
293:         wait_before_pass(args, pass).await;
294:         if !args.json {
295:             if truncated {
296:                 eprintln!(
297:                     "retrying {n} of {} file(s) (pass {pass} of {total}) — the retry set was \
298:                      truncated to the named report; re-run to converge the rest",
299:                     current.files_failed
300:                 );
301:             } else {
302:                 eprintln!("retrying {n} file(s) (pass {pass} of {total})");
303:             }
304:         }
305:         blit_core::remote::instrumentation::record_retry_pass(u64::from(pass));
306:         let mut pass_args = args.clone();
307:         pass_args.retry_only = Some(set);
308:         pass_args.retry_pass = Some((pass, total, n));
309:         // win-1: one heap allocation per pass keeps the pass's session
310:         // out of this loop's state and its caller's frame.
311:         let result = Box::pin(run(pass_args)).await?;
312:         added_files = added_files.saturating_add(result.files_transferred);
313:         added_bytes = added_bytes.saturating_add(result.bytes_transferred);
314:         in_stream_carrier_used |= result.in_stream_carrier_used;
315:         files_resumed = files_resumed.saturating_add(result.files_resumed);
316:         current = current.after_pass(n, truncated, result.failures);
317:         passes_run = pass;
318:     }
319:     if passes_run > 0 {
320:         current.mark_retried();
321:     }
322:     Ok(RetryOutcome {
323:         added_files,
324:         added_bytes,
325:         final_failures: current,
326:         passes_run,
327:         in_stream_carrier_used,
328:         files_resumed,
329:     })
330: }
